import { cacheLife, cacheTag } from 'next/cache'
import { getPosts } from '@/lib/api'

async function getCachedPosts() {
  'use cache'

  // Serve from cache for 1 hour, then revalidate in the background.
  cacheLife({ stale: 300, revalidate: 3600, expire: 86400 })
  // Invalidate on-demand with revalidateTag('posts').
  cacheTag('posts')

  return getPosts()
}

export default async function Home() {
  const posts = await getCachedPosts()

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>By {post.author}</p>
          </li>
        ))}
      </ul>
    </main>
  )
}

